"use client"

import React, { useState, useRef, KeyboardEvent } from 'react'
import { Send, Loader2 } from 'lucide-react'
import { cn } from '../lib/utils'

interface ChatInputProps {
  onSendMessage: (message: string) => void
  isLoading: boolean
  disabled?: boolean
}

export function ChatInput({ onSendMessage, isLoading, disabled = false }: ChatInputProps) {
  const [message, setMessage] = useState('')
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  const handleSend = () => {
    if (message.trim() && !isLoading && !disabled) {
      onSendMessage(message.trim())
      setMessage('')
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto'
      }
    }
  }

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }

  const handleTextareaChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setMessage(e.target.value)
    
    // Auto-resize textarea
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto'
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 200)}px`
    }
  }

  return (
    <div className="border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 p-4">
      <div className="max-w-4xl mx-auto">
        <div className="flex items-end gap-3">
          <div className="flex-1 relative">
            <textarea
              ref={textareaRef}
              value={message}
              onChange={handleTextareaChange}
              onKeyDown={handleKeyDown}
              placeholder="Type your message... (press Enter to send, Shift+Enter for new line)"
              disabled={disabled || isLoading}
              className={cn(
                "w-full px-4 py-3 rounded-2xl border border-gray-300 dark:border-gray-600",
                "bg-gray-50 dark:bg-gray-800 text-gray-900 dark:text-white",
                "placeholder-gray-500 dark:placeholder-gray-400",
                "resize-none focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent",
                "min-h-[50px] max-h-[200px]",
                (disabled || isLoading) && "opacity-50 cursor-not-allowed"
              )}
              style={{ height: 'auto' }}
            />
          </div>
          
          <button
            onClick={handleSend}
            disabled={!message.trim() || isLoading || disabled}
            className={cn(
              "flex items-center justify-center w-12 h-12 rounded-full",
              "bg-blue-500 hover:bg-blue-600 disabled:bg-gray-300 dark:disabled:bg-gray-600",
              "text-white transition-colors duration-200",
              "disabled:cursor-not-allowed"
            )}
          >
            {isLoading ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <Send className="w-5 h-5" />
            )}
          </button>
        </div>
        
        <div className="mt-2 text-xs text-gray-500 dark:text-gray-400 text-center">
          Try asking about weather or stock prices to see interactive components!
        </div>
      </div>
    </div>
  )
} 