"use client"

import React from 'react'
import { TrendingUp, TrendingDown, DollarSign, Calendar } from 'lucide-react'
import { cn } from '../lib/utils'

interface StockData {
  symbol: string
  companyName: string
  currentPrice: number
  change: number
  changePercent: number
  lastUpdate: string
  history: Array<{
    date: string
    price: number
  }>
}

interface StockCardProps {
  data: StockData
}

export function StockCard({ data }: StockCardProps) {
  const isPositive = data.change >= 0
  const maxPrice = Math.max(...data.history.map(h => h.price))
  const minPrice = Math.min(...data.history.map(h => h.price))
  const priceRange = maxPrice - minPrice

  return (
    <div className="bg-gradient-to-br from-green-50 to-emerald-100 dark:from-green-900/20 dark:to-emerald-800/20 rounded-xl p-6 border border-green-200 dark:border-green-700 shadow-lg">
      <div className="mb-4">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-1">
          Stock Price
        </h3>
        <p className="text-sm text-gray-600 dark:text-gray-400">{data.companyName}</p>
      </div>

      {/* Current Stock Info */}
      <div className="mb-6">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center space-x-4">
            <div className="p-3 bg-white/50 dark:bg-white/10 rounded-lg">
              <DollarSign className="w-6 h-6 text-green-600 dark:text-green-400" />
            </div>
            <div>
              <div className="text-2xl font-bold text-gray-900 dark:text-white">
                ${data.currentPrice.toFixed(2)}
              </div>
              <div className="text-lg font-semibold text-gray-600 dark:text-gray-400">
                {data.symbol}
              </div>
            </div>
          </div>
          <div className="text-right">
            <div className={cn(
              "flex items-center space-x-1 text-lg font-semibold",
              isPositive ? "text-green-600 dark:text-green-400" : "text-red-600 dark:text-red-400"
            )}>
              {isPositive ? <TrendingUp className="w-5 h-5" /> : <TrendingDown className="w-5 h-5" />}
              <span>{isPositive ? '+' : ''}{data.change.toFixed(2)}</span>
            </div>
            <div className={cn(
              "text-sm font-medium",
              isPositive ? "text-green-600 dark:text-green-400" : "text-red-600 dark:text-red-400"
            )}>
              ({isPositive ? '+' : ''}{data.changePercent.toFixed(2)}%)
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-2 text-sm text-gray-600 dark:text-gray-400">
          <Calendar className="w-4 h-4" />
          <span>Last updated: {new Date(data.lastUpdate).toLocaleString()}</span>
        </div>
      </div>

      {/* Price History Chart */}
      <div>
        <h4 className="text-sm font-medium text-gray-900 dark:text-white mb-3">
          10-Day Price History
        </h4>
        
        {/* Simple line chart representation */}
        <div className="bg-white/50 dark:bg-white/5 rounded-lg p-4 mb-4">
          <div className="relative h-24 flex items-end justify-between">
            {data.history.map((point, index) => {
              const height = priceRange > 0 ? ((point.price - minPrice) / priceRange) * 80 + 10 : 50
              return (
                <div
                  key={index}
                  className="flex flex-col items-center group relative"
                  style={{ width: `${100 / data.history.length}%` }}
                >
                  <div 
                    className="w-2 bg-gradient-to-t from-green-500 to-green-300 dark:from-green-400 dark:to-green-200 rounded-full transition-all duration-200 group-hover:w-3"
                    style={{ height: `${height}%` }}
                  />
                  {/* Tooltip */}
                  <div className="absolute bottom-full mb-2 hidden group-hover:block bg-gray-900 dark:bg-gray-100 text-white dark:text-gray-900 text-xs px-2 py-1 rounded whitespace-nowrap">
                    <div>${point.price.toFixed(2)}</div>
                    <div>{new Date(point.date).toLocaleDateString()}</div>
                  </div>
                </div>
              )
            })}
          </div>
        </div>

        {/* Price History List */}
        <div className="space-y-2 max-h-40 overflow-y-auto">
          {data.history.slice().reverse().map((point, index) => (
            <div 
              key={index}
              className="flex items-center justify-between p-2 bg-white/30 dark:bg-white/5 rounded-lg text-sm"
            >
              <span className="text-gray-600 dark:text-gray-400">
                {new Date(point.date).toLocaleDateString()}
              </span>
              <span className="font-medium text-gray-900 dark:text-white">
                ${point.price.toFixed(2)}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
} 