"use client"

import React, { useState } from 'react'
import { 
  Plus, 
  MessageSquare, 
  Trash2, 
  ChevronLeft, 
  ChevronRight, 
  Sun, 
  Moon,
  Menu
} from 'lucide-react'
import { useTheme } from '../contexts/ThemeContext'
import { cn } from '../lib/utils'

interface Chat {
  id: string
  title: string
  lastMessage: string
  timestamp: Date
}

interface SidebarProps {
  chats: Chat[]
  activeChat: string | null
  onSelectChat: (chatId: string) => void
  onNewChat: () => void
  onDeleteChat: (chatId: string) => void
  isCollapsed: boolean
  onToggleCollapse: () => void
}

export function Sidebar({
  chats,
  activeChat,
  onSelectChat,
  onNewChat,
  onDeleteChat,
  isCollapsed,
  onToggleCollapse
}: SidebarProps) {
  const { theme, toggleTheme } = useTheme()
  const [hoveredChat, setHoveredChat] = useState<string | null>(null)

  const truncateText = (text: string, maxLength: number) => {
    return text.length > maxLength ? text.substring(0, maxLength) + '...' : text
  }

  return (
    <>
      {/* Mobile menu button */}
      <button
        onClick={onToggleCollapse}
        className="lg:hidden fixed top-4 left-4 z-50 p-2 bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700"
      >
        <Menu className="w-5 h-5 text-gray-600 dark:text-gray-400" />
      </button>

      {/* Sidebar */}
      <div className={cn(
        "fixed lg:relative inset-y-0 left-0 z-40 flex flex-col",
        "bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700",
        "transition-all duration-300 ease-in-out",
        isCollapsed ? "w-16" : "w-80",
        // Mobile responsive
        "lg:translate-x-0",
        isCollapsed ? "-translate-x-full lg:translate-x-0" : "translate-x-0"
      )}>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700">
          {!isCollapsed && (
            <h1 className="text-lg font-semibold text-gray-900 dark:text-white">
              AI Chat
            </h1>
          )}
          <button
            onClick={onToggleCollapse}
            className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-lg transition-colors"
          >
            {isCollapsed ? (
              <ChevronRight className="w-5 h-5 text-gray-600 dark:text-gray-400" />
            ) : (
              <ChevronLeft className="w-5 h-5 text-gray-600 dark:text-gray-400" />
            )}
          </button>
        </div>

        {/* New Chat Button */}
        <div className="p-4">
          <button
            onClick={onNewChat}
            className={cn(
              "flex items-center gap-3 w-full p-3 rounded-lg",
              "bg-blue-500 hover:bg-blue-600 text-white",
              "transition-colors duration-200",
              isCollapsed ? "justify-center" : "justify-start"
            )}
          >
            <Plus className="w-5 h-5" />
            {!isCollapsed && <span className="font-medium">New Chat</span>}
          </button>
        </div>

        {/* Chat History */}
        <div className="flex-1 overflow-y-auto px-4">
          {!isCollapsed && (
            <h2 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-3">
              Recent Chats
            </h2>
          )}
          <div className="space-y-2">
            {chats.map((chat) => (
              <div
                key={chat.id}
                className={cn(
                  "group relative flex items-center gap-3 p-3 rounded-lg cursor-pointer",
                  "hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors",
                  activeChat === chat.id && "bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-700",
                  isCollapsed ? "justify-center" : "justify-start"
                )}
                onClick={() => onSelectChat(chat.id)}
                onMouseEnter={() => setHoveredChat(chat.id)}
                onMouseLeave={() => setHoveredChat(null)}
              >
                <MessageSquare className={cn(
                  "w-5 h-5 flex-shrink-0",
                  activeChat === chat.id 
                    ? "text-blue-600 dark:text-blue-400" 
                    : "text-gray-400 dark:text-gray-500"
                )} />
                
                {!isCollapsed && (
                  <>
                    <div className="flex-1 min-w-0">
                      <div className={cn(
                        "font-medium text-sm truncate",
                        activeChat === chat.id 
                          ? "text-blue-900 dark:text-blue-100" 
                          : "text-gray-900 dark:text-white"
                      )}>
                        {truncateText(chat.title, 25)}
                      </div>
                      <div className="text-xs text-gray-500 dark:text-gray-400 truncate">
                        {truncateText(chat.lastMessage, 30)}
                      </div>
                      <div className="text-xs text-gray-400 dark:text-gray-500">
                        {chat.timestamp.toLocaleDateString()}
                      </div>
                    </div>
                    
                    {hoveredChat === chat.id && (
                      <button
                        onClick={(e) => {
                          e.stopPropagation()
                          onDeleteChat(chat.id)
                        }}
                        className="opacity-0 group-hover:opacity-100 p-1.5 hover:bg-red-100 dark:hover:bg-red-900/20 rounded-lg transition-all"
                      >
                        <Trash2 className="w-4 h-4 text-red-500" />
                      </button>
                    )}
                  </>
                )}

                {/* Tooltip for collapsed mode */}
                {isCollapsed && (
                  <div className="absolute left-full ml-2 px-2 py-1 bg-gray-900 dark:bg-gray-100 text-white dark:text-gray-900 text-sm rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none z-50">
                    {chat.title}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Theme Toggle */}
        <div className="p-4 border-t border-gray-200 dark:border-gray-700">
          <button
            onClick={toggleTheme}
            className={cn(
              "flex items-center gap-3 w-full p-3 rounded-lg",
              "hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors",
              isCollapsed ? "justify-center" : "justify-start"
            )}
          >
            {theme === 'light' ? (
              <Moon className="w-5 h-5 text-gray-600 dark:text-gray-400" />
            ) : (
              <Sun className="w-5 h-5 text-gray-600 dark:text-gray-400" />
            )}
            {!isCollapsed && (
              <span className="text-sm text-gray-700 dark:text-gray-300">
                {theme === 'light' ? 'Dark Mode' : 'Light Mode'}
              </span>
            )}
          </button>
        </div>
      </div>

      {/* Overlay for mobile */}
      {!isCollapsed && (
        <div 
          className="lg:hidden fixed inset-0 bg-black/50 z-30"
          onClick={onToggleCollapse}
        />
      )}
    </>
  )
} 