"use client"

import React from 'react'
import { Bot, User } from 'lucide-react'
import { WeatherCard } from './WeatherCard'
import { StockCard } from './StockCard'
import { cn } from '../lib/utils'

interface Message {
  id: string
  role: 'user' | 'assistant'
  content: string
  components?: Array<{
    type: 'weather' | 'stock'
    data: any
  }>
  timestamp: Date
}

interface ChatMessageProps {
  message: Message
}

export function ChatMessage({ message }: ChatMessageProps) {
  const isUser = message.role === 'user'

  return (
    <div className={cn(
      "flex gap-3 max-w-4xl mx-auto px-4 py-6",
      isUser ? "justify-end" : "justify-start"
    )}>
      {!isUser && (
        <div className="flex-shrink-0 w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center">
          <Bot className="w-5 h-5 text-white" />
        </div>
      )}

      <div className={cn(
        "flex flex-col max-w-3xl",
        isUser ? "items-end" : "items-start"
      )}>
        <div className={cn(
          "rounded-2xl px-4 py-3 max-w-full",
          isUser 
            ? "bg-blue-500 text-white" 
            : "bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-white"
        )}>
          <div className="whitespace-pre-wrap break-words">
            {message.content}
          </div>
        </div>

        {/* Render components if present */}
        {message.components && message.components.length > 0 && (
          <div className="mt-4 space-y-4 w-full max-w-md">
            {message.components.map((component, index) => (
              <div key={index}>
                {component.type === 'weather' && (
                  <WeatherCard data={component.data} />
                )}
                {component.type === 'stock' && (
                  <StockCard data={component.data} />
                )}
              </div>
            ))}
          </div>
        )}

        <div className={cn(
          "text-xs text-gray-500 dark:text-gray-400 mt-1",
          isUser ? "text-right" : "text-left"
        )}>
          {message.timestamp.toLocaleTimeString()}
        </div>
      </div>

      {isUser && (
        <div className="flex-shrink-0 w-8 h-8 bg-green-500 rounded-full flex items-center justify-center">
          <User className="w-5 h-5 text-white" />
        </div>
      )}
    </div>
  )
} 