"use client"

import React, { useState, useRef, useEffect } from 'react'
import { Sidebar } from './components/Sidebar'
import { ChatMessage } from './components/ChatMessage'
import { ChatInput } from './components/ChatInput'
import { cn } from './lib/utils'

interface Message {
  id: string
  role: 'user' | 'assistant'
  content: string
  components?: Array<{
    type: 'weather' | 'stock'
    data: any
  }>
  timestamp: Date
}

interface Chat {
  id: string
  title: string
  messages: Message[]
  lastMessage: string
  timestamp: Date
}

export default function Home() {
  const [chats, setChats] = useState<Chat[]>([])
  const [activeChat, setActiveChat] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false)
  const [streamingMessage, setStreamingMessage] = useState<Message | null>(null)
  
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const abortControllerRef = useRef<AbortController | null>(null)

  // Scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [chats, activeChat, streamingMessage])

  // Initialize with a default chat
  useEffect(() => {
    if (chats.length === 0) {
      handleNewChat()
    }
  }, [])

  const getCurrentChat = () => {
    return chats.find(chat => chat.id === activeChat)
  }

  const generateChatTitle = (message: string) => {
    const words = message.split(' ').slice(0, 6).join(' ')
    return words.length > 30 ? words.substring(0, 30) + '...' : words
  }

  const handleNewChat = () => {
    const newChat: Chat = {
      id: Date.now().toString(),
      title: 'New Chat',
      messages: [],
      lastMessage: '',
      timestamp: new Date()
    }
    setChats(prev => [newChat, ...prev])
    setActiveChat(newChat.id)
  }

  const handleSelectChat = (chatId: string) => {
    setActiveChat(chatId)
    setIsSidebarCollapsed(window.innerWidth < 1024) // Auto-collapse on mobile
  }

  const handleDeleteChat = (chatId: string) => {
    setChats(prev => prev.filter(chat => chat.id !== chatId))
    if (activeChat === chatId) {
      const remainingChats = chats.filter(chat => chat.id !== chatId)
      if (remainingChats.length > 0) {
        setActiveChat(remainingChats[0].id)
      } else {
        handleNewChat()
      }
    }
  }

  const handleSendMessage = async (content: string) => {
    if (!activeChat || isLoading) return

    // Cancel any ongoing request
    if (abortControllerRef.current) {
      abortControllerRef.current.abort()
    }

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date()
    }

    // Update chat with user message
    setChats(prev => prev.map(chat => {
      if (chat.id === activeChat) {
        const updatedMessages = [...chat.messages, userMessage]
        return {
          ...chat,
          messages: updatedMessages,
          title: chat.messages.length === 0 ? generateChatTitle(content) : chat.title,
          lastMessage: content,
          timestamp: new Date()
        }
      }
      return chat
    }))

    setIsLoading(true)
    
    // Initialize streaming message
    const assistantMessage: Message = {
      id: (Date.now() + 1).toString(),
      role: 'assistant',
      content: '',
      timestamp: new Date()
    }
    setStreamingMessage(assistantMessage)

    try {
      // Create new abort controller for this request
      abortControllerRef.current = new AbortController()

      const currentChat = getCurrentChat()
      const messages = currentChat ? [...currentChat.messages, userMessage] : [userMessage]

      const response = await fetch('http://127.0.0.1:8000/chat/stream', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          messages: messages.map(msg => ({
            role: msg.role,
            content: msg.content
          })),
          include_components: true
        }),
        signal: abortControllerRef.current.signal
      })

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`)
      }

      const reader = response.body?.getReader()
      if (!reader) {
        throw new Error('No reader available')
      }

      let fullContent = ''
      let components: Array<{ type: 'weather' | 'stock', data: any }> = []

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        const chunk = new TextDecoder().decode(value)
        const lines = chunk.split('\n')

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            try {
              const data = JSON.parse(line.slice(6))
              
              if (data.type === 'text') {
                fullContent += data.content
                setStreamingMessage(prev => prev ? {
                  ...prev,
                  content: fullContent
                } : null)
              } else if (data.type === 'component') {
                components.push(data.component)
              } else if (data.type === 'done') {
                // Streaming complete
                break
              } else if (data.type === 'error') {
                throw new Error(data.error)
              }
            } catch (e) {
              console.error('Error parsing SSE data:', e)
            }
          }
        }
      }

      // Add final message to chat
      const finalMessage: Message = {
        ...assistantMessage,
        content: fullContent,
        components: components.length > 0 ? components : undefined
      }

      setChats(prev => prev.map(chat => {
        if (chat.id === activeChat) {
          return {
            ...chat,
            messages: [...chat.messages, finalMessage],
            lastMessage: fullContent.substring(0, 100),
            timestamp: new Date()
          }
        }
        return chat
      }))

    } catch (error: any) {
      if (error.name !== 'AbortError') {
        console.error('Chat error:', error)
        
        const errorMessage: Message = {
          ...assistantMessage,
          content: 'Sorry, I encountered an error. Please make sure the backend server is running and try again.',
        }

        setChats(prev => prev.map(chat => {
          if (chat.id === activeChat) {
            return {
              ...chat,
              messages: [...chat.messages, errorMessage],
              lastMessage: 'Error occurred',
              timestamp: new Date()
            }
          }
          return chat
        }))
      }
    } finally {
      setIsLoading(false)
      setStreamingMessage(null)
      abortControllerRef.current = null
    }
  }

  const currentChat = getCurrentChat()
  const allMessages = currentChat ? [...currentChat.messages] : []
  if (streamingMessage) {
    allMessages.push(streamingMessage)
  }

  return (
    <div className="flex h-screen bg-white dark:bg-gray-900">
      <Sidebar
        chats={chats.map(chat => ({
          id: chat.id,
          title: chat.title,
          lastMessage: chat.lastMessage,
          timestamp: chat.timestamp
        }))}
        activeChat={activeChat}
        onSelectChat={handleSelectChat}
        onNewChat={handleNewChat}
        onDeleteChat={handleDeleteChat}
        isCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
      />

      {/* Main Chat Area */}
      <div className={cn(
        "flex-1 flex flex-col transition-all duration-300",
        "lg:ml-0", // Remove margin on large screens since sidebar is relative
        isSidebarCollapsed ? "lg:ml-16" : "lg:ml-80"
      )}>
        {/* Chat Header */}
        <div className="border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 p-4">
          <div className="max-w-4xl mx-auto">
            <h1 className="text-xl font-semibold text-gray-900 dark:text-white">
              {currentChat?.title || 'AI Chat'}
            </h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              Ask me anything! Try asking about weather or stock prices for interactive components.
            </p>
          </div>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto bg-gray-50 dark:bg-gray-800">
          {allMessages.length === 0 ? (
            <div className="flex items-center justify-center h-full">
              <div className="text-center max-w-md mx-auto p-8">
                <div className="text-4xl mb-4">💬</div>
                <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
                  Start a conversation
                </h2>
                <p className="text-gray-600 dark:text-gray-400 mb-6">
                  Ask me anything! I can help with general questions and provide interactive components for weather and stock information.
                </p>
                <div className="space-y-2 text-sm text-gray-500 dark:text-gray-400">
                  <p>💡 Try asking: "What's the weather in New York?"</p>
                  <p>💡 Or: "Show me Apple stock price"</p>
                </div>
              </div>
            </div>
          ) : (
            <div className="space-y-0">
              {allMessages.map((message) => (
                <ChatMessage key={message.id} message={message} />
              ))}
              <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Chat Input */}
        <ChatInput
          onSendMessage={handleSendMessage}
          isLoading={isLoading}
          disabled={!activeChat}
        />
      </div>
    </div>
  )
}
