"use client"

import React from 'react'
import { Cloud, CloudRain, Sun, Wind, Droplets } from 'lucide-react'
import { cn } from '../lib/utils'

interface WeatherData {
  location: string
  current: {
    temperature: number
    condition: string
    humidity: number
    windSpeed: number
    icon: string
  }
  forecast: Array<{
    day: string
    high: number
    low: number
    condition: string
    icon: string
  }>
}

interface WeatherCardProps {
  data: WeatherData
}

const getWeatherIcon = (icon: string, size: number = 24) => {
  const iconClass = `w-${size === 24 ? '6' : '8'} h-${size === 24 ? '6' : '8'}`
  
  switch (icon) {
    case 'sun':
      return <Sun className={cn(iconClass, "text-yellow-500")} />
    case 'cloudy':
      return <Cloud className={cn(iconClass, "text-gray-500")} />
    case 'partly-cloudy':
      return <Cloud className={cn(iconClass, "text-gray-400")} />
    case 'rain':
      return <CloudRain className={cn(iconClass, "text-blue-500")} />
    default:
      return <Sun className={cn(iconClass, "text-yellow-500")} />
  }
}

export function WeatherCard({ data }: WeatherCardProps) {
  return (
    <div className="bg-gradient-to-br from-blue-50 to-blue-100 dark:from-blue-900/20 dark:to-blue-800/20 rounded-xl p-6 border border-blue-200 dark:border-blue-700 shadow-lg">
      <div className="mb-4">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-1">
          Weather
        </h3>
        <p className="text-sm text-gray-600 dark:text-gray-400">{data.location}</p>
      </div>

      {/* Current Weather */}
      <div className="mb-6">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center space-x-4">
            {getWeatherIcon(data.current.icon, 32)}
            <div>
              <div className="text-3xl font-bold text-gray-900 dark:text-white">
                {data.current.temperature}°C
              </div>
              <div className="text-sm text-gray-600 dark:text-gray-400">
                {data.current.condition}
              </div>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4 text-sm">
          <div className="flex items-center space-x-2 text-gray-600 dark:text-gray-400">
            <Droplets className="w-4 h-4" />
            <span>Humidity: {data.current.humidity}%</span>
          </div>
          <div className="flex items-center space-x-2 text-gray-600 dark:text-gray-400">
            <Wind className="w-4 h-4" />
            <span>Wind: {data.current.windSpeed} km/h</span>
          </div>
        </div>
      </div>

      {/* 5-Day Forecast */}
      <div>
        <h4 className="text-sm font-medium text-gray-900 dark:text-white mb-3">
          5-Day Forecast
        </h4>
        <div className="space-y-2">
          {data.forecast.map((day, index) => (
            <div 
              key={index}
              className="flex items-center justify-between p-3 bg-white/50 dark:bg-white/5 rounded-lg"
            >
              <div className="flex items-center space-x-3">
                {getWeatherIcon(day.icon)}
                <div>
                  <div className="text-sm font-medium text-gray-900 dark:text-white">
                    {day.day}
                  </div>
                  <div className="text-xs text-gray-500 dark:text-gray-400">
                    {day.condition}
                  </div>
                </div>
              </div>
              <div className="text-right">
                <div className="text-sm font-medium text-gray-900 dark:text-white">
                  {day.high}°
                </div>
                <div className="text-xs text-gray-500 dark:text-gray-400">
                  {day.low}°
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
} 